use super::*;

/// Parse an entry log, skipping lines that do not parse.
///
/// A corrupt line is SKIPPED rather than failing the read: the log is append-only and written by a
/// live producer, so a torn final line is an ordinary race, not a broken feed. Returning `Failing`
/// for it would blank the widget every time a write landed mid-read.
pub fn parse_entries(text: &str) -> Vec<Entry> {
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .filter_map(|l| serde_json::from_str::<Entry>(l).ok())
        .collect()
}
